import * as React from "react"

import { cn } from "@/lib/utils"

type AlertProps = React.ComponentProps<"div"> & {
  /** error is for something that failed and needs fixing; it takes role="alert" and the signal colour. */
  variant?: "default" | "error"
  /** Draw the bar and bring the lines in one by one. Set it when the alert appears because of something the person did. */
  arriving?: boolean
}

/** A double bar: in a score, the sign that something changes here. */
function Alert({ className, variant = "default", arriving, ...props }: AlertProps) {
  return (
    <div
      data-slot="alert"
      data-variant={variant === "error" ? "error" : undefined}
      data-arriving={arriving || undefined}
      role={variant === "error" ? "alert" : "status"}
      className={cn("db-alert", className)}
      {...props}
    />
  )
}

function AlertTitle({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="alert-title" className={cn("db-alert-title", className)} {...props} />
}

function AlertDescription({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="alert-description" className={cn("db-alert-description", className)} {...props} />
}

function AlertActions({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="alert-actions" className={cn("db-alert-actions", className)} {...props} />
}

export { Alert, AlertTitle, AlertDescription, AlertActions, type AlertProps }

@layer components {
  /* ── db-alert ── a double bar: in a score, the sign that something changes here */
  .db-alert { --c: var(--db-ink); position: relative; display: grid; justify-items: start; gap: var(--db-space-2); padding-inline-start: calc(var(--db-space-5) + 5px); color: var(--db-graphite); }
  .db-alert::before {
    content: ""; position: absolute; inset-block: 0.3em 0.2em; inset-inline-start: 0; width: 5px; transform-origin: 50% 0;
    background: linear-gradient(var(--c), var(--c)) 0 0 / var(--db-hairline) 100% no-repeat, linear-gradient(var(--c), var(--c)) 100% 0 / var(--db-stroke) 100% no-repeat;
  }
  .db-alert-title { font-size: var(--db-mp); line-height: var(--db-mp-lh); color: var(--db-ink); }
  .db-alert[data-variant="error"] { --c: var(--db-signal); }
  .db-alert[data-variant="error"] .db-alert-title { color: var(--db-signal); }
  .db-alert-actions { display: flex; flex-wrap: wrap; gap: var(--db-space-5); margin-block-start: var(--db-space-2); }
  .db-alert[data-arriving]::before { animation: db-draw-y var(--db-andante) var(--db-exhale) backwards; }
  .db-alert[data-arriving] > * { animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; animation-delay: calc(160ms + (sibling-index() - 1) * 2 * var(--db-arpeggio)); }
}
